    for (int i = 0; i < 31; i++) {
        acc = acc * 3 + i;
        if (i == 12) uflag = (unsigned int)(acc ^ 0xcc0cu);
    }
    idg = acc % 2569;
    strv = (short)(acc & 0x7f);
    report(acc);
    return acc;
}

int main(void) {
